



use crate::type_chart::Type;

pub type MoveId = u16;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Category {
    Physical,
    Special,
    Status,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum MoveTarget {

    Normal,

    Self_,


    AllAdjacent,

    AllAdjacentFoes,

    All,

    AllySide,

    FoeSide,



    AdjacentAlly,
}



#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ChoiceTarget {

    None,

    Adjacent,

    AdjacentFoe,

    AdjacentAlly,

    AllyOrSelf,
}






#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FieldEffect {


    WideGuard,


    QuickGuard,

    CraftyShield,

    MatBlock,

    IonDeluge,
    Rain,
    Sun,
    Sand,
    Snow,
    Hail,
    Tailwind,
    TrickRoom,
    Reflect,
    LightScreen,



    AuroraVeil,




    StealthRock,



    Spikes,


    ToxicSpikes,

    StickyWeb,





    ElectricTerrain,





    GrassyTerrain,



    MistyTerrain,





    PsychicTerrain,

    Gravity,

    FairyLock,

    MagicRoom,

    WonderRoom,

    Safeguard,

    Mist,

    LuckyChant,

    MudSport,
    WaterSport,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Accuracy {


    AlwaysHits,
    Percent(u8),
}





#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SecondaryEffect {
    Status(Status),

    Boosts([i8; 7]),
    Flinch,

    SelfBoosts([i8; 7]),




    RandomStatus([Status; 3]),
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Secondary {
    pub chance: u8,
    pub effect: SecondaryEffect,
}




#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
pub enum Status {
    Burn = 1,
    Freeze = 2,
    Paralysis = 3,
    Poison = 4,
    Toxic = 5,
    Sleep = 6,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct MoveData {
    pub move_type: Type,
    pub category: Category,
    pub base_power: u16,
    pub accuracy: Accuracy,
    pub pp: u8,
    pub priority: i8,
    pub target: MoveTarget,
    pub choice_target: ChoiceTarget,





    pub crit_ratio: u8,
    pub blocked_by_protect: bool,


    pub thaws_user: bool,

    pub sleep_usable: bool,



    pub call_flags: u16,




    pub contact: bool,

    pub sound: bool,


    pub reflectable: bool,

    pub will_crit: bool,

    pub breaks_protect: bool,

    pub charge: bool,

    pub recharge: bool,

    pub punch: bool,


    pub minimize: bool,

    pub slicing: bool,

    pub multihit_min: u8,
    pub multihit_max: u8,

    pub multiaccuracy: bool,

    pub pulse: bool,

    pub bullet: bool,

    pub heal_flag: bool,

    pub gravity_flag: bool,

    pub powder: bool,

    pub bypass_sub: bool,

    pub bite: bool,


    pub self_boosts: Option<[i8; 7]>,


    pub boosts: Option<[i8; 7]>,

    pub status: Option<Status>,
    pub secondary: Option<Secondary>,


    pub secondary2: Option<Secondary>,



    pub recoil: Option<(u32, u32)>,




    pub drain: Option<(u32, u32)>,



    pub heal: Option<(u32, u32)>,
    pub field_effect: Option<FieldEffect>,




    pub self_switch: bool,
}


